export class NavigationTransaction {
  private pointer = 0;
  private resolve: VoidFunction = () => {
    /* Empty */
  };
  private reject: VoidFunction = () => {
    /* Empty */
  };
  private promise: Promise<void> = new Promise((resolve, reject) => {
    this.resolve = resolve;
    this.reject = reject;
  });

  constructor(private actions: VoidFunction[]) {}

  get isMultiAction(): boolean {
    return this.actions.length > 1;
  }

  get donePromise(): Promise<void> {
    return this.promise;
  }

  get finished(): boolean {
    return this.pointer >= this.actions.length;
  }

  doNext(): void {
    if (!this.finished) {
      const action = this.actions[this.pointer];
      this.pointer++;
      action();
    }

    // this.finished изменился при выполнении предыдущего условия - нельзя объединить в if-else.
    if (this.finished) {
      this.resolve();
    }
  }
}

import { NavigationTransaction } from '../entities/NavigationTransaction';

export class TransactionExecutor {
  private static instance?: TransactionExecutor;
  private transactions: NavigationTransaction[] = [];

  // eslint-disable-next-line @typescript-eslint/no-empty-function
  private constructor() {}

  public static getInstance() {
    if (!TransactionExecutor.instance) {
      TransactionExecutor.instance = new TransactionExecutor();
    }

    return TransactionExecutor.instance;
  }

  public static get isRunSyncActive() {
    const transactionExecutor = TransactionExecutor.getInstance();
    const hasMultipleTransactions = transactionExecutor.transactions.length > 1;
    const hasSingleMultiActionTransaction =
      transactionExecutor.transactions.length === 1 &&
      transactionExecutor.transactions[0].isMultiAction;

    return hasMultipleTransactions || hasSingleMultiActionTransaction;
  }

  public static add(transaction: NavigationTransaction) {
    const transactionExecutor = TransactionExecutor.getInstance();
    transactionExecutor.transactions.push(transaction);
  }

  public static resetTransactions() {
    const transactionExecutor = TransactionExecutor.getInstance();
    transactionExecutor.transactions = [];
  }

  public static async doNext(): Promise<void> {
    const transactionExecutor = TransactionExecutor.getInstance();
    const transactions = transactionExecutor.transactions;
    if (transactions.length) {
      transactions[0].doNext();
      if (transactions[0]?.finished) {
        transactions.shift();
      }
    }
  }
}

import { useLocation } from './hooks';
import { RelativeRoutingType } from '@remix-run/router';
import { useCallback, useContext, useMemo, useRef } from 'react';
import {
  createSearchParams,
  getSearchParamsForLocation,
  URLSearchParamsInit,
} from '../utils/createSearchParams';
import { RouterContext } from '../contexts';
import { warning } from '../utils/utils';

export interface NavigateOptions {
  replace?: boolean;
  state?: any;
  preventScrollReset?: boolean;
  relative?: RelativeRoutingType;
}

export type SetURLSearchParams = (
  nextInit?: URLSearchParamsInit | ((prev: URLSearchParams) => URLSearchParamsInit),
  navigateOpts?: NavigateOptions,
) => void;

/**
 * A convenient wrapper for reading and writing search parameters via the
 * URLSearchParams interface.
 */
export function useSearchParams(
  defaultInit?: URLSearchParamsInit,
): [URLSearchParams, SetURLSearchParams] {
  warning(
    typeof URLSearchParams !== 'undefined',
    'You cannot use the `useSearchParams` hook in a browser that does not ' +
      'support the URLSearchParams API. If you need to support Internet ' +
      'Explorer 11, we recommend you load a polyfill such as ' +
      'https://github.com/ungap/url-search-params\n\n' +
      "If you're unsure how to load polyfills, we recommend you check out " +
      'https://polyfill.io/v3/ which provides some recommendations about how ' +
      'to load polyfills only for users that need them, instead of for every ' +
      'user.',
  );

  let defaultSearchParamsRef = useRef(createSearchParams(defaultInit));
  let hasSetSearchParamsRef = useRef(false);

  let location = useLocation();
  let searchParams = useMemo(
    () =>
      // Only merge in the defaults if we haven't yet called setSearchParams.
      // Once we call that we want those to take precedence, otherwise you can't
      // remove a param with setSearchParams({}) if it has an initial value
      getSearchParamsForLocation(
        location.search,
        hasSetSearchParamsRef.current ? null : defaultSearchParamsRef.current,
      ),
    [location.search],
  );

  let router = useContext(RouterContext).router;
  let setSearchParams = useCallback<SetURLSearchParams>(
    (nextInit, navigateOptions) => {
      const newSearchParams = createSearchParams(
        typeof nextInit === 'function' ? nextInit(searchParams) : nextInit,
      );
      hasSetSearchParamsRef.current = true;
      router.navigate(`${location.pathname}?${newSearchParams}`, navigateOptions);
    },
    [router, searchParams, location.pathname],
  );

  return [searchParams, setSearchParams];
}

export type ParamKeyValuePair = [string, string];

export type URLSearchParamsInit =
  | string
  | ParamKeyValuePair[]
  | Record<string, string | string[]>
  | URLSearchParams;

function convertObjectToURLInit(init: Record<string, string | string[]>) {
  return Object.keys(init).reduce<ParamKeyValuePair[]>((memo, key) => {
    const value = init[key];
    return memo.concat(Array.isArray(value) ? value.map((v) => [key, v]) : [[key, value]]);
  }, []);
}

/**
 * Creates a URLSearchParams object using the given initializer.
 *
 * This is identical to `new URLSearchParams(init)` except it also
 * supports arrays as values in the object form of the initializer
 * instead of just strings. This is convenient when you need multiple
 * values for a given key, but don't want to use an array initializer.
 *
 * For example, instead of:
 *
 *   let searchParams = new URLSearchParams([
 *     ['sort', 'name'],
 *     ['sort', 'price']
 *   ]);
 *
 * you can do:
 *
 *   let searchParams = createSearchParams({
 *     sort: ['name', 'price']
 *   });
 */
export function createSearchParams(init: URLSearchParamsInit = ''): URLSearchParams {
  const inputIsReadyForInstantiation =
    typeof init === 'string' || Array.isArray(init) || init instanceof URLSearchParams;
  return new URLSearchParams(inputIsReadyForInstantiation ? init : convertObjectToURLInit(init));
}

export function getSearchParamsForLocation(
  locationSearch: string,
  defaultSearchParams: URLSearchParams | null,
) {
  const searchParams = createSearchParams(locationSearch);

  if (defaultSearchParams) {
    for (let key of defaultSearchParams.keys()) {
      if (!searchParams.has(key)) {
        defaultSearchParams.getAll(key).forEach((value) => {
          searchParams.append(key, value);
        });
      }
    }
  }

  return searchParams;
}

import { Router as RemixRouter } from '@remix-run/router/dist/router';
import { createKey } from './utils';
import { createBrowserHistory, createRouter } from '@remix-run/router';
import { RouteWithoutRoot, RouteWithRoot } from '../type';
import { InitialLocation } from '../services/InitialLocation';

export function createBrowserRouter(routes: RouteWithRoot[] | RouteWithoutRoot[]): RemixRouter {
  // Задать новый key для новой локации в случае, если приложение уже запущено,
  // а пользователь делает переход изменив hash в адресной строке браузера.
  window.addEventListener('popstate', (event: PopStateEvent) => {
    if (!event.state) {
      window.history.replaceState({ key: createKey() }, '');
    }
  });
  const history = createBrowserHistory();
  InitialLocation.init(history.location);
  return createRouter({
    history,
    routes: routes.map((item) => ({ ...item, index: true })),
  }).initialize();
}

# vue-routing-app
Пример интеграции приложения на Vue и Vue Router во ВКонтакте
с помощью библиотеки `@vkontakte/vk-bridge`.

Показывает:
- как запустить приложение
- как обновить URL основной страницы, куда встроено приложение
- как принять путь из основной страницы при открытии приложения
- как обеспечить корректную работу браузерных и нативных кнопок назад и вперед

## Запуск проекта
```
yarn install
```

### Запуск в режиме разработки с горячей перезагрузкой
```
yarn serve
```

### Проверка стиля кода
```
yarn lint
```

